class Solution { private fun topTwo(count:Map<Int,Int>):IntArray{var topValue=-1;var top=0;var second=0;for((value,frequency) in count)if(frequency>top){second=top;top=frequency;topValue=value}else if(frequency>second)second=frequency;return intArrayOf(topValue,top,second)};fun minimumOperations(nums:IntArray):Int{val even=HashMap<Int,Int>();val odd=HashMap<Int,Int>();for(i in nums.indices){val count=if(i%2==0)even else odd;count[nums[i]]=(count[nums[i]]?:0)+1};val a=topTwo(even);val b=topTwo(odd);val kept=if(a[0]!=b[0])a[1]+b[1]else maxOf(a[1]+b[2],a[2]+b[1]);return nums.size-kept} }
